<script setup lang="ts">
import AccountRecovery from '../components/AccountRecovery.vue'
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { PASSWORD_MAX_LENGTH,EXISTING_PASSWORD_MAX_LENGTH,passwordPolicyError } from '../auth/password-policy'
import { post } from '../api/client'
import type { StorageProbe } from '../api/types'
import { useSystemStore } from '../stores/system'
import StatusBadge from '../components/StatusBadge.vue'
const auth=useAuthStore(),router=useRouter(),currentPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),changingPassword=ref(false),passwordError=ref('')
async function changePassword(){passwordError.value='';const policyError=passwordPolicyError(newPassword.value);if(policyError){passwordError.value=policyError;return};if(newPassword.value!==confirmPassword.value){passwordError.value='两次输入的新密码不一致';return};changingPassword.value=true;try{await auth.changePassword(currentPassword.value,newPassword.value,confirmPassword.value);currentPassword.value='';newPassword.value='';confirmPassword.value='';await router.replace('/login')}catch(e){passwordError.value=e instanceof Error?e.message:'密码修改失败'}finally{changingPassword.value=false}}
const system=useSystemStore(),checking=ref(''),checkError=ref(''),checkMessage=ref('')
async function check(kind:'cloud'|'emby'){
 checking.value=kind;checkError.value='';checkMessage.value=''
 try{
  if(kind==='cloud'){const result=await post<StorageProbe>('/cloudStorage/test',{});checkMessage.value=result.pathReadable?'CloudDrive2 已就绪，凭据可读取配置根目录。仍需文件诊断和真实播放验收。':'CloudDrive2 未通过目录读取验证'}
  else{await post('/emby/test',{});checkMessage.value='Emby 公共信息接口可达。用户权限与播放器播放需另行验证。'}
  await system.refresh()
 }catch(e){checkError.value=e instanceof Error?e.message:'连接检查失败'}finally{checking.value=''}
}
const variables=[{name:'LOG_LEVEL',description:'内置 JSON 日志：debug / info / warn / error。通过 docker compose logs app 查看，Docker 自动限额轮转。'},{name:'DATABASE_URL',description:'PostgreSQL 连接；执行迁移后开启持久化任务。'},{name:'REDIS_URL',description:'Redis 缓存连接；缓存不保存唯一业务事实。'},{name:'CLOUDDRIVE_ENDPOINT / CLOUDDRIVE_TOKEN',description:'CloudDrive2 接入参数；原生 gRPC 地址及只读 API Token；也支持 CloudDrive2 账号登录刷新。'},{name:'STRM_PROXY_FALLBACK / STRM_FORCE_PROXY',description:'直链要求特定 UA/请求头时采用受控代理；强制代理用于排查客户端重定向问题。'},{name:'PLAYBACK_ALLOWED_HOSTS',description:'可选 CDN 域名允许列表；默认拒绝私网 DNS 结果。'},{name:'APP_PUBLIC_URL',description:'STRM 固定链接域名。Vue 开发模式应配置为 http://localhost:5173。'},{name:'STRM_ALLOWED_ROOTS',description:'允许解析的网盘根目录，多项以逗号分隔。'},{name:'EMBY_UPSTREAM_URL / EMBY_PROXY_ENABLED',description:'基础反代；EMBY_302_ENABLED 开启最小静态流拦截，客户端兼容性需实测。'}]
</script>
<template><section class="page-heading"><div><h1>连接与系统设置</h1><p>管理账号、服务连接和运行配置。部署参数修改后重启相应服务。</p></div><el-button :loading="system.loading" @click="system.refresh">检查依赖状态</el-button></section><section class="note-panel section-gap"><strong>业务凭据现在可以在界面配置</strong><p>CloudDrive2、下载器、Emby、TMDB、Telegram 和站点账号使用加密连接管理。</p><RouterLink to="/integrations" class="inline-link">打开服务连接</RouterLink></section><section class="panel account-settings"><div class="panel-title"><h2>管理员账号</h2><span class="muted">{{auth.account?.username}}</span></div><p class="field-hint">修改密码后撤销所有已登录会话，包括当前会话。需要使用新密码重新登录。</p><el-alert v-if="passwordError" :title="passwordError" type="error" :closable="false"/><form class="connection-form" @submit.prevent="changePassword"><label for="current-password">当前密码</label><el-input id="current-password" v-model="currentPassword" type="password" show-password autocomplete="current-password" :maxlength="EXISTING_PASSWORD_MAX_LENGTH"/><label for="new-password">新密码</label><el-input id="new-password" v-model="newPassword" type="password" show-password autocomplete="new-password" :maxlength="PASSWORD_MAX_LENGTH"/><p class="field-hint">6–20个字符，支持空格和中文。</p><label for="confirm-new-password">确认新密码</label><el-input id="confirm-new-password" v-model="confirmPassword" type="password" show-password autocomplete="new-password" :maxlength="PASSWORD_MAX_LENGTH"/><el-button native-type="submit" type="primary" :loading="changingPassword" :disabled="!currentPassword||!newPassword||!confirmPassword">修改密码并重新登录</el-button></form></section><AccountRecovery/><section class="panel"><div class="panel-title"><h2>实际连接状态</h2><span class="muted">不保存或展示明文凭据</span></div><div v-for="dep in system.status?.dependencies??[]" :key="dep.id" class="dependency-row"><div><strong>{{dep.name}}</strong><p class="muted">{{dep.message}}</p></div><StatusBadge :state="dep.state"/></div></section><section class="panel section-gap"><div class="panel-title"><h2>主动连接验证</h2><span class="muted">使用服务器配置，不在浏览器填写接入密钥</span></div><div class="heading-actions"><el-button :loading="checking==='cloud'" :disabled="checking!==''&&checking!=='cloud'" @click="check('cloud')">验证 CloudDrive2</el-button><el-button :loading="checking==='emby'" :disabled="checking!==''&&checking!=='emby'" @click="check('emby')">验证 Emby</el-button></div><el-alert v-if="checkError" :title="checkError" type="error" :closable="false" show-icon class="diagnosis-alert"/><el-alert v-if="checkMessage" :title="checkMessage" type="success" :closable="false" show-icon class="diagnosis-alert"/><p class="field-hint">未配置地址和凭据时明确报告缺失。不要把只读连接检查当作实际视频播放成功。</p></section><section class="panel section-gap"><div class="panel-title"><h2>环境变量</h2><span class="muted">参考 .env.example</span></div><dl class="config-list"><div v-for="item in variables" :key="item.name"><dt><code>{{item.name}}</code></dt><dd>{{item.description}}</dd></div></dl></section><section class="note-panel"><strong>密钥分离</strong><p>管理员使用注册的账号密码登录；SESSION_SECRET_KEY 仅在服务端签署会话，不是登录密码；STRM_API_KEY 仅用于允许目录内的播放解析，不能用来访问管理 API。不要提交 .env，或把示例中的真实凭据写入代码。</p></section></template>

<style scoped>.account-settings{margin-bottom:24px}.account-settings .connection-form{max-width:480px}.account-settings .el-button{justify-self:start;margin-top:10px}</style>
